package com.bank.factorial;

import java.math.BigInteger;
import java.util.logging.*;

public class FactorialDemo {
    private static final Logger log = Logger.getLogger("Factorial");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        FactorialService service = new FactorialService();
        log.info(() -> "5!  (long)       = " + service.factorial(5));     // 120
        log.info(() -> "0!  (long)       = " + service.factorial(0));     // 1
        log.info(() -> "25! (BigInteger) = " + service.factorialBig(25)); // huge, exact
    }
}

// ─── Would be in service/FactorialService.java ───
class FactorialService {
    // long version with overflow DETECTION (throws past 20!)
    long factorial(int n) {
        return java.util.stream.LongStream.rangeClosed(1, n)
            .reduce(1, Math::multiplyExact);   // identity 1 → 0! == 1; multiplyExact → safe
    }

    // BigInteger version for large n (no overflow)
    BigInteger factorialBig(int n) {
        return java.util.stream.IntStream.rangeClosed(1, n)
            .mapToObj(BigInteger::valueOf)
            .reduce(BigInteger.ONE, BigInteger::multiply);
    }
}
